(() => {
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels={support:'서로에게 주는 도움',strengths:'잘 맞는 순간',risks:'부딪히는 순간',affection:'애정과 대화',money:'돈과 공동생활',individual_risks:'각자의 약점'};
  function findings(items,kind){return `<div class="pair-findings ${kind}">${items.map(x=>`<article><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p><details class="chapter-evidence"><summary>왜 이렇게 읽었나요?</summary><p>${esc(x.basis)}</p></details></article>`).join('')}</div>`;}
  function comparison(c){
    const cards=c.people.map(p=>{const r=p.report,b=r.balance,first=r.chapters.find(x=>x.topic==='overview');return `<article class="pair-person"><span>${esc(p.name)}</span><h3>${esc(first?.title||'나만의 사주 이야기')}</h3><p>${esc(r.profile.birth_date)} · ${esc(r.profile.birth_time||'시간 미입력')} · ${esc(r.profile.city)}</p><details class="chapter-evidence"><summary>이 사람의 사주 계산표</summary><div class="pair-pillars">${r.pillars.map(x=>`<span>${esc(x.label)} <b>${esc(x.known?x.ganji:'미입력')}</b></span>`).join('')}</div><p>${b.available?`강약 ${esc(b.strength)} · 용신 ${esc(b.yong_element||'미선택')} (${esc(b.yong_method)})`:'시간이 없어 전체 균형 미확정'}</p></details></article>`;}).join('');
    return `<p class="pair-status">${esc(c.status)}</p>${c.warnings.map(x=>`<p class="time-boundary-note">${esc(x)}</p>`).join('')}<div class="pair-people">${cards}</div>${!c.chapters.length?'<p role="status">두 사람의 계산을 바탕으로 자세한 궁합 풀이를 작성하고 있어요.</p>':''}<nav class="pair-outline" aria-label="궁합 항목으로 이동">${c.chapters.map(x=>`<button data-pair-chapter="pair-${x.topic}">${labels[x.topic]}</button>`).join('')}</nav>${c.chapters.map(x=>`<details id="pair-${x.topic}" class="pair-chapter reading-fold" data-reading-fold ${x.topic==='support'?'open':''}><summary><span class="report-overline">${labels[x.topic]}</span><h3>${esc(x.title)}</h3><span class="fold-mark" aria-hidden="true">+</span></summary><div class="pair-chapter-content">${x.topic==='risks'&&c.risks.length?findings(c.risks,'pair-risks'):x.topic==='strengths'&&c.strengths.length?findings(c.strengths,'pair-strengths'):x.paragraphs.map(p=>`<p class="chapter-body">${esc(p)}</p>`).join('')}</div></details>`).join('')}<details class="chapter-evidence pair-evidence"><summary>두 명식 사이의 글자 관계와 계산 범위 <span>+</span></summary><p>각자의 명식은 별도로 유지해요. 아래는 두 사람 사이에서 확인한 지지의 두 글자 관계입니다. 일지끼리는 ‘일지 비교’로 표시하고, 다른 자리의 관계를 같은 중요도로 세지 않아요.</p>${c.cross_relations.length?c.cross_relations.map(x=>`<p>${esc(c.people[0].name)} ${esc(x.left_label)} ${esc(x.left)} ↔ ${esc(c.people[1].name)} ${esc(x.right_label)} ${esc(x.right)} · <b>${esc(x.kind)}</b>${x.primary?' · 일지 비교':''}</p>`).join(''):'<p>이 두 글자 관계표에서 검출한 관계가 없어요.</p>'}${c.directions.map(d=>`<p>${esc(d.receiver)} ← ${esc(d.other)}: ${d.available?`${esc(d.element)} 용신 · ${esc(d.method)} · 상대 겉 글자 ${d.visible_count}개`:'시간 미입력으로 보완 방향 미확정'}${d.matches.map(m=>`<br>${esc(m.position)} ${esc(m.part)} ${esc(m.character)}`).join('')}</p>`).join('')}<p>기운의 일치는 전통적인 비교 기준이에요. 기운이 전달되거나 상대의 실제 성격을 계산했다는 뜻은 아니며, 생활 장면은 이해를 돕는 자체 해석의 예시입니다.</p><p>${esc(c.scope)}</p></details>`;
  }
  function render(c){return `<section class="compatibility-report"><nav class="pair-view-nav" aria-label="궁합과 각자의 사주 보기"><button data-pair-view="comparison" aria-pressed="true">두 사람 궁합</button>${c.people.map((p,i)=>`<button data-pair-view="${i}" aria-pressed="false">${esc(p.name)} 사주</button>`).join('')}</nav><p class="pair-view-help">각자의 사주를 읽은 뒤, 두 사람 궁합에서 보완과 마찰을 함께 비교해요.</p><div class="pair-view-body">${comparison(c)}</div></section>`;}
  function mount(root,c,onTerm){
    const panel=root.querySelector('.pair-view-body'),buttons=[...root.querySelectorAll('[data-pair-view]')];
    function bindJumps(){panel.querySelectorAll('[data-pair-chapter]').forEach(b=>b.addEventListener('click',()=>(()=>{const target=panel.querySelector('#'+b.dataset.pairChapter);if(target){target.open=true;target.scrollIntoView({block:'start'});}})()));}
    buttons.forEach(b=>b.addEventListener('click',()=>{buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const value=b.dataset.pairView;if(value==='comparison'){panel.innerHTML=comparison(c);bindJumps();}else{panel.innerHTML=window.MoaReport.render(c.people[Number(value)].report);panel.querySelectorAll('#tab-astrology,#tab-name,#panel-astrology,#panel-name').forEach(x=>x.remove());window.MoaReport.mount(panel,onTerm);}root.querySelector('.pair-view-nav').scrollIntoView({block:'start'});}));bindJumps();
  }
  window.MoaCompatibility={render,mount};
})();
